  $('rfRefresh').onclick=refreshTraining;$('rfTrain').onclick=async()=>{try{$('rfTrain').disabled=true;status('Creating an immutable dataset snapshot and queueing candidate training…');const response=await fetch('/api/training/jobs',{method:'POST',headers:{'Content-Type':'application/json','X-Touchline-Client':'studio'},body:JSON.stringify({epochs:Number($('rfEpochs').value),imgsz:Number($('rfSize').value),batch:Number($('rfBatch').value)})}),data=await response.json();if(!response.ok)throw Error(data.error||'Could not start training');status('Candidate training queued. You can close this review; the PC must stay on.');refreshTraining();}catch(e){status(e.message,true);refreshTraining();}};
  function close(){if(busy){status('Wait for the frame operation to finish before closing.');return;}persist();el.close();}
  $('rfClose').onclick=close;el.addEventListener('cancel',e=>{e.preventDefault();close();});el.addEventListener('close',()=>{token++;clearTimeout(pollTimer);media.pause();media.removeAttribute('src');media.load();if(url)URL.revokeObjectURL(url);url=null;});
  async function open(){try{context=options.context();options.pause();el.showModal();busy=true;frame=null;doc=null;selection=-1;available=false;$('rfTrain').disabled=true;$('rfComplete').checked=false;status('Identifying the source video…');const generation=++token;let hash=hashes.get(context.file);if(!hash){hash=await Core.hashFile(context.file,p=>status(`Identifying the source video · ${p}%`));hashes.set(context.file,hash);}if(generation!==token)return;db=await openDb();let saved=await read(hash);if(saved){try{Core.validateDocument(saved);}catch{saved=null;}}doc=saved||{schema:'touchline-groundtruth-v1',source_sha256:hash,source_name:context.file.name,match_id:'',split:'train',frames:[]};
try{const response=await fetch('/api/library/reviews/'+hash);if(response.ok){const stored=await response.json();for(const record of stored.records||[]){if(record.source_sha256!==hash)continue;Core.validateFrame(record.frame,true);const index=doc.frames.findIndex(f=>Math.abs(f.t-record.frame.t)<.000001);if(index<0)doc.frames.push(copy(record.frame));else if(doc.frames[index].reviewed&&String(record.reviewed_utc)>String(doc.frames[index].reviewed_utc||''))doc.frames[index]=copy(record.frame);if(!doc.match_id){doc.match_id=record.match_id;doc.split=record.split;}}}}catch{}if(generation!==token)return;$('rfHash').textContent='Video SHA-256: '+hash.slice(0,16)+'…';$('rfMatch').value=doc.match_id||'';$('rfSplit').value=doc.split||'train';url=URL.createObjectURL(context.file);await waitFor('loadeddata',()=>{media.src=url;media.load();});doc.width=media.videoWidth;doc.height=media.videoHeight;doc.duration=media.duration;$('rfFps').value=context.fps||doc.navigation_fps||30;busy=false;await captureTime(context.time);refreshTraining();}catch(e){busy=false;status(e.message,true);options.toast(e.message);}}
  options.button.onclick=open;
  return {open};
